const homeSeo=`<section class="tool-seo-home section-muted"><div class="container"><p class="eyebrow">CRAKKER X WORLD AI · OFFICIAL WEBSITE</p><h2>Crakker X World — official website of CrakkerXworld.AI</h2><h3>Online PDF and image conversion services</h3><p>Crakker X World is the name visitors may search for when looking for CrakkerXworld.AI. The official website at crakkerxai.com brings common document and image tasks together in one browser-based workspace. Convert JPG, PNG and WebP images to PDF, turn PDF pages into PNG or JPG images, merge PDF files, extract selected pages, rotate documents, convert image formats, resize pictures and compress image files. Choose a tool above to process your files on your device.</p><div class="tool-seo-home-grid"><section><h3>PDF tools</h3><p>Prepare, organize and convert PDF documents with focused tools.</p><ul><li><a href="${link('tools/images-to-pdf/',0)}">Images to PDF</a> — combine pictures into one PDF.</li><li><a href="${link('tools/pdf-to-png/',0)}">PDF to PNG</a> — convert document pages to images.</li><li><a href="${link('tools/merge-pdf/',0)}">Merge PDF</a> — combine multiple PDF files.</li><li><a href="${link('tools/extract-pdf-pages/',0)}">Extract PDF Pages</a> and <a href="${link('tools/rotate-pdf/',0)}">Rotate PDF</a>.</li></ul></section><section><h3>Image tools</h3><p>Change image format, dimensions and file size.</p><ul><li><a href="${link('tools/convert-image/',0)}">Convert Image</a> — JPG, PNG and WebP formats.</li><li><a href="${link('tools/resize-image/',0)}">Resize Image</a> — set image dimensions in pixels.</li><li><a href="${link('tools/compress-image/',0)}">Compress Image</a> — optimize image size and quality.</li></ul></section></div><p class="tool-seo-home-note">Files for these eight conversion tools are processed locally in your browser. The combined selected input limit is 50 MB per conversion task. Browser memory and file compatibility can affect very large or unusual documents.</p><p><a class="seo-guide-link" href="${link('how-it-works/',0)}">Read how the tools work</a> · <a class="seo-guide-link" href="${link('privacy/',0)}">Review file privacy</a></p></div></section>`;
const homeAudience=`<section class="tool-seo-home"><div class="container"><p class="eyebrow muted">DESIGNED FOR INDIVIDUALS, TEAMS AND ORGANIZATIONS</p><h2>One conversion workspace for every scale of work</h2><div class="tool-seo-home-grid"><section><h3>Students and educators</h3><p>Combine photographed notes into a PDF, extract selected pages from reading material, or turn a PDF page into an image for a presentation.</p></section><section><h3>Office and admin teams</h3><p>Join reports, rotate scanned pages, collect supporting documents and resize image files for forms or internal workflows.</p></section><section><h3>Enterprise and large organizations</h3><p>Support document operations, administrative teams and distributed departments with repeatable browser-based file conversions. For high-volume or regulated workflows, assess your organization’s browser, device and governance requirements before processing sensitive material.</p></section><section><h3>Developers and professional teams</h3><p>Prepare assets, standardize image dimensions and organize PDF deliverables for product, engineering, design and operations workflows.</p></section><section><h3>Creators and growing businesses</h3><p>Convert pictures between common formats, prepare image dimensions and reduce image size before sharing or publishing.</p></section></div><h2>How a conversion works</h2><ol><li>Open the tool that matches your task and choose files from your device.</li><li>Set the available options, such as page ranges, output format or image dimensions.</li><li>Run the conversion and save the result using the download link. For the eight public converters, processing runs in your browser.</li></ol><p class="tool-seo-home-note">The browser tools do not upload selected file contents to the conversion server. Account, feedback, advertising and optional AI Updates features use separate website services described in the <a href="privacy/">Privacy Policy</a>.</p></div></section>`;
const homeFaq=`<section class="tool-seo-home section-muted"><div class="container"><p class="eyebrow">COMMON QUESTIONS</p><h2>Before you start</h2><div class="faq-list"><details><summary>Do I need to install software?</summary><p>No. Open a tool in a modern browser, choose your files and download the result. JavaScript must be enabled.</p></details><details><summary>Are my PDF and image files uploaded?</summary><p>The eight public conversion tools process selected file contents locally in your browser. The files are not sent to the conversion server by the conversion code.</p></details><details><summary>What is the free conversion input limit?</summary><p>The public browser converters enforce a combined 50 MB input limit per task. Individual tools also have format, page-count or image-dimension limits.</p></details><details><summary>Where can I get help?</summary><p>Use the <a href="contact/">Contact Us</a> page or send a message through the <a href="feedback/">Feedback &amp; Bug Reports</a> form.</p></details></div><p><a class="seo-guide-link" href="faq/">Read all frequently asked questions</a></p></div></section>`;
